:root {
  --bg: #0a0e14;
  --bg-soft: #101623;
  --panel: #131a29;
  --border: #1e2a3d;
  --text: #dfe7f5;
  --text-dim: #6b7a93;
  --accent: #39ffa0;
  --accent-2: #00e5ff;
  --danger: #ff4d6d;
  --gold: #ffd166;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html,
body {
  height: 100%;
}

body {
  font-family: 'Segoe UI', 'PingFang SC', 'Microsoft YaHei', system-ui, sans-serif;
  background:
    radial-gradient(1200px 700px at 50% -10%, rgba(57, 255, 160, 0.08), transparent 60%),
    radial-gradient(900px 600px at 90% 110%, rgba(0, 229, 255, 0.07), transparent 55%),
    var(--bg);
  color: var(--text);
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  overflow: hidden;
}

.game-shell {
  width: min(92vw, 640px);
  padding: 20px 0;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

/* ---------- HUD ---------- */
.hud {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
}

.title {
  font-size: 30px;
  letter-spacing: 6px;
  font-weight: 800;
  color: var(--accent);
  text-shadow: 0 0 18px rgba(57, 255, 160, 0.55);
  line-height: 1;
}

.title span {
  color: var(--text-dim);
  text-shadow: none;
  font-weight: 600;
}

.stats {
  display: flex;
  gap: 24px;
}

.stat {
  text-align: right;
}

.stat-label {
  display: block;
  font-size: 10px;
  letter-spacing: 3px;
  color: var(--text-dim);
}

.stat-value {
  font-size: 26px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--text);
}

.stat-value.gold {
  color: var(--gold);
}

/* ---------- Board ---------- */
.board-wrap {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  border-radius: 14px;
  padding: 8px;
  background: linear-gradient(160deg, var(--panel), var(--bg-soft));
  box-shadow:
    0 0 0 1px var(--border),
    0 18px 50px rgba(0, 0, 0, 0.55),
    inset 0 0 60px rgba(0, 229, 255, 0.04);
}

#board {
  display: block;
  width: 100%;
  height: 100%;
  border-radius: 9px;
  background: #080c13;
}

/* ---------- Overlay ---------- */
.overlay {
  position: absolute;
  inset: 8px;
  border-radius: 9px;
  background: rgba(6, 9, 15, 0.78);
  backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: opacity 0.25s ease;
  z-index: 5;
}

.overlay.hidden {
  opacity: 0;
  pointer-events: none;
}

.overlay-panel {
  text-align: center;
  padding: 28px 34px;
  border-radius: 14px;
  background: rgba(16, 22, 35, 0.85);
  border: 1px solid var(--border);
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.6);
  min-width: min(78vw, 320px);
}

.overlay-title {
  font-size: 30px;
  letter-spacing: 8px;
  color: var(--accent);
  text-shadow: 0 0 22px rgba(57, 255, 160, 0.6);
  margin-bottom: 10px;
}

.overlay-title.danger {
  color: var(--danger);
  text-shadow: 0 0 22px rgba(255, 77, 109, 0.6);
}

.overlay-text {
  color: var(--text-dim);
  font-size: 14px;
  margin-bottom: 22px;
  line-height: 1.7;
}

.overlay-text .final-score {
  color: var(--gold);
  font-size: 18px;
  font-weight: 700;
}

.btn {
  font-family: inherit;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 4px;
  padding: 12px 34px;
  border: none;
  border-radius: 8px;
  color: #04110a;
  background: linear-gradient(135deg, var(--accent), var(--accent-2));
  cursor: pointer;
  box-shadow: 0 6px 24px rgba(57, 255, 160, 0.35);
  transition: transform 0.12s ease, box-shadow 0.12s ease;
}

.btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 10px 30px rgba(57, 255, 160, 0.5);
}

.btn:active {
  transform: translateY(0);
}

/* ---------- Footer hint ---------- */
.controls-hint {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  color: var(--text-dim);
  font-size: 12px;
  letter-spacing: 1px;
}

kbd {
  font-family: inherit;
  font-size: 11px;
  font-weight: 600;
  color: var(--text);
  background: var(--bg-soft);
  border: 1px solid var(--border);
  border-bottom-width: 2px;
  border-radius: 5px;
  padding: 3px 8px;
}

.sep {
  width: 1px;
  height: 14px;
  background: var(--border);
  margin: 0 6px;
}

'use strict';

/* ============================================================
 * NEON SNAKE — 原生 Canvas 贪吃蛇
 * grid_logic 类型：离散网格、步进移动、碰撞判定
 * ============================================================ */

const COLS = 24;
const ROWS = 24;
const BASE_STEP_MS = 140;      // 初始步进间隔
const MIN_STEP_MS = 60;        // 最快步进间隔
const SPEEDUP_PER_FOOD = 2;    // 每吃一个食物减少的毫秒数

const canvas = document.getElementById('board');
const ctx = canvas.getContext('2d');
const scoreEl = document.getElementById('score');
const bestEl = document.getElementById('best');
const overlay = document.getElementById('overlay');
const overlayTitle = document.getElementById('overlay-title');
const overlayText = document.getElementById('overlay-text');
const startBtn = document.getElementById('start-btn');

/* ---------- 高分屏适配 ---------- */
const SIZE = 600;
const DPR = Math.min(window.devicePixelRatio || 1, 2);
canvas.width = SIZE * DPR;
canvas.height = SIZE * DPR;
ctx.scale(DPR, DPR);

const CELL = SIZE / COLS;

/* ---------- 游戏状态 ---------- */
let snake = [];        // 蛇身坐标数组，head 为 index 0
let dir = { x: 1, y: 0 };
let inputQueue = [];   // 输入缓冲（每次步进最多消费一个）
let food = null;
let score = 0;
let best = Number(localStorage.getItem('neon-snake-best') || 0);
let running = false;   // 是否正在移动
let paused = false;
let gameOver = false;
let timerId = null;
let animId = null;
let foodPulse = 0;

bestEl.textContent = best;

/* ============================================================
 * 初始化 / 重置
 * ============================================================ */
function resetGame() {
  snake = [
    { x: 6, y: 12 },
    { x: 5, y: 12 },
    { x: 4, y: 12 },
    { x: 3, y: 12 },
  ];
  dir = { x: 1, y: 0 };
  inputQueue = [];
  score = 0;
  paused = false;
  gameOver = false;
  scoreEl.textContent = '0';
  spawnFood();
}

function spawnFood() {
  const free = [];
  for (let y = 0; y < ROWS; y++) {
    for (let x = 0; x < COLS; x++) {
      if (!snake.some((s) => s.x === x && s.y === y)) free.push({ x, y });
    }
  }
  if (free.length === 0) {
    food = null; // 蛇占满全屏 → 胜利
    return;
  }
  food = free[Math.floor(Math.random() * free.length)];
}

/* ============================================================
 * 核心步进
 * ============================================================ */
function step() {
  if (!running || paused || gameOver) return;

  // 消费一个输入
  while (inputQueue.length > 0) {
    const next = inputQueue.shift();
    // 不允许原地掉头（同方向 / 反方向）
    if (next.x !== -dir.x || next.y !== -dir.y) {
      if (next.x !== dir.x || next.y !== dir.y) {
        dir = next;
        break;
      }
    }
  }

  const head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };

  // 撞墙
  if (head.x < 0 || head.x >= COLS || head.y < 0 || head.y >= ROWS) {
    return endGame();
  }
  // 撞自身（注意：尾部单元格本步会移走，除非本步吃到食物不缩短）
  const willGrow = food && head.x === food.x && head.y === food.y;
  const bodyToCheck = willGrow ? snake : snake.slice(0, -1);
  if (bodyToCheck.some((s) => s.x === head.x && s.y === head.y)) {
    return endGame();
  }

  snake.unshift(head);

  if (willGrow) {
    score += 10;
    scoreEl.textContent = score;
    spawnFood();
    scheduleStep();
  } else {
    snake.pop();
  }
}

function scheduleStep() {
  const interval = Math.max(MIN_STEP_MS, BASE_STEP_MS - score / 10 * SPEEDUP_PER_FOOD);
  clearTimeout(timerId);
  timerId = setTimeout(step, interval);
}

/* ============================================================
 * 结束 / 开始 / 暂停
 * ============================================================ */
function endGame() {
  running = false;
  gameOver = true;
  clearTimeout(timerId);
  if (score > best) {
    best = score;
    localStorage.setItem('neon-snake-best', String(best));
    bestEl.textContent = best;
    bestEl.classList.add('gold');
  }
  overlayTitle.textContent = 'GAME OVER';
  overlayTitle.classList.add('danger');
  overlayText.innerHTML =
    `本局得分 <span class="final-score">${score}</span><br>` +
    (score >= best && score > 0 ? '🎉 新纪录！' : '再试一次，冲击纪录！');
  startBtn.textContent = '再来一局';
  showOverlay();
}

function startGame() {
  resetGame();
  overlayTitle.textContent = 'READY?';
  overlayTitle.classList.remove('danger');
  bestEl.classList.remove('gold');
  hideOverlay();
  running = true;
  scheduleStep();
}

function togglePause() {
  if (!running || gameOver) return;
  paused = !paused;
  if (paused) {
    clearTimeout(timerId);
    overlayTitle.textContent = 'PAUSED';
    overlayTitle.classList.remove('danger');
    overlayText.innerHTML = '按 <kbd style="color:#dfe7f5">Space</kbd> 或点击下方按钮继续';
    startBtn.textContent = '继续';
    showOverlay();
  } else {
    hideOverlay();
    scheduleStep();
  }
}

function showOverlay() {
  overlay.classList.remove('hidden');
}

function hideOverlay() {
  overlay.classList.add('hidden');
}

/* ============================================================
 * 输入
 * ============================================================ */
const KEY_DIR = {
  w: { x: 0, y: -1 },
  a: { x: -1, y: 0 },
  s: { x: 0, y: 1 },
  d: { x: 1, y: 0 },
  arrowup: { x: 0, y: -1 },
  arrowleft: { x: -1, y: 0 },
  arrowdown: { x: 0, y: 1 },
  arrowright: { x: 1, y: 0 },
};

window.addEventListener('keydown', (e) => {
  const key = e.key.toLowerCase();
  if (key === ' ' || key === 'spacebar') {
    e.preventDefault();
    togglePause();
    return;
  }
  if (key === 'enter') {
    if (!running || gameOver) startGame();
    return;
  }
  const next = KEY_DIR[key];
  if (!next) return;
  e.preventDefault();
  if (!running) {
    if (gameOver) startGame();
    return;
  }
  // 缓冲去重：与当前输入队列末尾相同则忽略
  const last = inputQueue[inputQueue.length - 1];
  if (!last || last.x !== next.x || last.y !== next.y) {
    inputQueue.push({ ...next });
    if (inputQueue.length > 2) inputQueue.splice(0, inputQueue.length - 2);
  }
});

startBtn.addEventListener('click', () => {
  if (gameOver) startGame();
  else if (paused) togglePause();
  else startGame();
});

/* ============================================================
 * 渲染
 * ============================================================ */
function lerp(a, b, t) {
  return a + (b - a) * t;
}

function hslGradient(t) {
  // t: 0=头(翠绿) → 1=尾(青蓝)
  return `hsl(${lerp(150, 190, t).toFixed(1)}, 100%, ${lerp(55, 45, t).toFixed(1)}%)`;
}

function draw() {
  // 背景
  ctx.fillStyle = '#080c13';
  ctx.fillRect(0, 0, SIZE, SIZE);

  // 细网格线
  ctx.strokeStyle = 'rgba(57, 255, 160, 0.05)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  for (let i = 1; i < COLS; i++) {
    ctx.moveTo(i * CELL, 0);
    ctx.lineTo(i * CELL, SIZE);
    ctx.moveTo(0, i * CELL);
    ctx.lineTo(SIZE, i * CELL);
  }
  ctx.stroke();

  // 食物（脉动光晕）
  if (food) {
    foodPulse = (foodPulse + 0.06) % (Math.PI * 2);
    const glow = 6 + Math.sin(foodPulse) * 3;
    const cx = food.x * CELL + CELL / 2;
    const cy = food.y * CELL + CELL / 2;
    const r = CELL * 0.32;
    const grad = ctx.createRadialGradient(cx, cy, r * 0.3, cx, cy, r + glow);
    grad.addColorStop(0, 'rgba(255, 77, 109, 0.95)');
    grad.addColorStop(0.6, 'rgba(255, 77, 109, 0.45)');
    grad.addColorStop(1, 'rgba(255, 77, 109, 0)');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(cx, cy, r + glow, 0, Math.PI * 2);
    ctx.fill();
    // 食物核心
    ctx.fillStyle = '#ff4d6d';
    ctx.beginPath();
    ctx.arc(cx, cy, r, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,0.7)';
    ctx.beginPath();
    ctx.arc(cx - r * 0.25, cy - r * 0.25, r * 0.22, 0, Math.PI * 2);
    ctx.fill();
  }

  // 蛇（头→尾 渐变 + 发光）
  if (snake.length > 0) {
    ctx.save();
    ctx.shadowColor = 'rgba(57, 255, 160, 0.45)';
    ctx.shadowBlur = 12;

    const pad = CELL * 0.12;
    const r = CELL * 0.18;
    for (let i = snake.length - 1; i >= 0; i--) {
      const s = snake[i];
      const t = snake.length === 1 ? 0 : i / (snake.length - 1);
      const px = s.x * CELL + pad;
      const py = s.y * CELL + pad;
      const size = CELL - pad * 2;

      // 越靠近头越亮、越大
      const scale = 1 - t * 0.18;
      const inset = size * (1 - scale) / 2;
      ctx.fillStyle = hslGradient(t);
      roundRect(px + inset, py + inset, size * scale, size * scale, r * scale * 2);
      ctx.fill();
    }

    // 眼睛（头）
    const head = snake[0];
    const hx = head.x * CELL + CELL / 2;
    const hy = head.y * CELL + CELL / 2;
    ctx.shadowBlur = 0;
    ctx.fillStyle = '#ffffff';
    const eyeOff = CELL * 0.16;
    const eyeR = CELL * 0.08;
    const perp = { x: -dir.y, y: dir.x };
    for (const side of [-1, 1]) {
      const ex = hx + dir.x * CELL * 0.18 + perp.x * eyeOff * side;
      const ey = hy + dir.y * CELL * 0.18 + perp.y * eyeOff * side;
      ctx.beginPath();
      ctx.arc(ex, ey, eyeR, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#10151f';
      ctx.beginPath();
      ctx.arc(ex + dir.x * eyeR * 0.4, ey + dir.y * eyeR * 0.4, eyeR * 0.45, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#ffffff';
    }
    ctx.restore();
  }

  animId = requestAnimationFrame(draw);
}

function roundRect(x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

/* ---------- 启动 ---------- */
resetGame();
draw();

